def calculate_total(lines: list[OrderLine], tax_rate: Decimal, discount: Decimal) -> Decimal:
    """Return the order total including tax, rounded to cents.

    `discount` is a fraction in [0, 1) taken off the subtotal before tax.
    """
    if not Decimal("0") <= discount < Decimal("1"):
        raise ValueError("discount must be in [0, 1)")
    subtotal = sum((line.unit_price * line.quantity for line in lines), Decimal("0"))
    discounted = subtotal * (1 - discount)
    return (discounted * (1 + tax_rate)).quantize(CENT)

